package com.bank.transfer.pool;

import java.util.concurrent.Semaphore;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

// Models a bounded pool like HikariCP. A permit = a database connection.
public class ConnectionPool {
    private final Semaphore permits;          // bounds concurrent borrowers
    private final int maxSize;
    private final AtomicInteger active = new AtomicInteger(0);
    private final AtomicInteger waiting = new AtomicInteger(0);
    private final long timeoutMs;

    public ConnectionPool(int maxSize, long timeoutMs) {
        this.maxSize = maxSize;
        this.timeoutMs = timeoutMs;
        this.permits = new Semaphore(maxSize, true); // fair ordering
    }

    // Borrow a connection, or fail if none is free within the timeout.
    public void borrow() throws InterruptedException {
        waiting.incrementAndGet();
        boolean got = permits.tryAcquire(timeoutMs, TimeUnit.MILLISECONDS);
        waiting.decrementAndGet();
        if (!got) {
            throw new IllegalStateException(
                "connection is not available, request timed out after " + timeoutMs + "ms");
        }
        active.incrementAndGet();
    }

    // Return a connection to the pool.
    public void release() {
        active.decrementAndGet();
        permits.release();
    }

    public int getActive()  { return active.get(); }
    public int getIdle()    { return maxSize - active.get(); }
    public int getWaiting() { return waiting.get(); }
    public int getMaxSize() { return maxSize; }
}
