package com.bank.transfer.ops;

import com.bank.transfer.pool.ConnectionPool;
import java.util.logging.Logger;

// Reports exactly the numbers the runbook asks the on-call engineer to check.
public class PoolMetrics {
    private static final Logger log = Logger.getLogger(PoolMetrics.class.getName());
    private final ConnectionPool pool;

    public PoolMetrics(ConnectionPool pool) { this.pool = pool; }

    public void report() {
        // These three lines mirror the actuator metrics named in the runbook.
        log.info(() -> "hikaricp.connections.active  = " + pool.getActive());
        log.info(() -> "hikaricp.connections.idle    = " + pool.getIdle());
        log.info(() -> "hikaricp.connections.pending = " + pool.getWaiting());
        if (pool.getActive() == pool.getMaxSize() && pool.getWaiting() > 0) {
            log.warning("POOL EXHAUSTED -> follow runbook db-connection-pool-exhausted.md");
        }
    }
}
