package com.bank.transfer.service;

import com.bank.transfer.model.Account;
import com.bank.transfer.pool.ConnectionPool;
import java.math.BigDecimal;
import java.util.logging.Level;
import java.util.logging.Logger;

// Borrows a connection, performs the debit/credit, always releases.
public class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());
    private final ConnectionPool pool;

    public TransferService(ConnectionPool pool) { this.pool = pool; }

    public void transfer(Account from, Account to, BigDecimal amount) {
        try {
            pool.borrow(); // may time out when the pool is exhausted
            try {
                from.debit(amount);
                to.credit(amount);
                log.info(() -> "transfer " + amount + " " + from.getAccountId()
                        + "->" + to.getAccountId() + " OK");
                Thread.sleep(50); // simulate a query holding the connection
            } finally {
                pool.release(); // ALWAYS return the connection, even on error
            }
        } catch (IllegalStateException e) {
            log.log(Level.SEVERE, "transfer failed: " + e.getMessage(), e);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}
