package com.bank.transfer;

import com.bank.transfer.model.Account;
import com.bank.transfer.ops.PoolMetrics;
import com.bank.transfer.pool.ConnectionPool;
import com.bank.transfer.service.TransferService;
import java.math.BigDecimal;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class TransferDemo {
    public static void main(String[] args) throws Exception {
        ConnectionPool pool = new ConnectionPool(10, 2000); // max 10, 2s timeout
        TransferService service = new TransferService(pool);
        PoolMetrics metrics = new PoolMetrics(pool);

        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        // Fire 50 concurrent transfers against a pool of only 10 -> exhaustion.
        ExecutorService executor = Executors.newFixedThreadPool(50);
        for (int i = 0; i < 50; i++) {
            executor.submit(() -> service.transfer(rajesh, priya, new BigDecimal("1000")));
        }
        Thread.sleep(100);
        metrics.report(); // print the numbers the runbook references

        executor.shutdown();
        executor.awaitTermination(10, TimeUnit.SECONDS);
        metrics.report(); // print again after the storm clears
    }
}
